window.dataLayer=window.dataLayer||[];const CURRENCY='RUB';function formatPrice(price){if(price==null)return 0;return parseFloat(String(price).replace(/\s+/g,'').replace(',','.'))||0;}
document.addEventListener('ecommerce',function(e){if(!e.detail){console.warn('Ecommerce event is missing detail object');return;}
const{type,products,action}=e.detail;if(!type||!products||!products.length){console.warn('Invalid ecommerce event:',e.detail);return;}
const payload={ecommerce:{currencyCode:CURRENCY,[type]:{...(action&&{actionField:action}),products:products.map(p=>({id:p.id,name:p.name,price:formatPrice(p.price),...(p.quantity&&{quantity:p.quantity}),...(p.brand&&{brand:p.brand}),...(p.category&&{category:p.category}),...(p.variant&&{variant:p.variant})}))}}};console.log('Pushing ecommerce event:',payload);window.dataLayer.push(payload);});window.trackEcommerce=function(type,products,action){const event=new CustomEvent('ecommerce',{detail:{type,products,action}});document.dispatchEvent(event);};;